export type DpsTier = 'S' | 'A' | 'B' | 'C' | 'D';

export type WeaponClass =
  | 'Assault Rifle'
  | 'SMG'
  | 'LMG'
  | 'Marksman Rifle'
  | 'Sniper'
  | 'Shotgun'
  | 'Pistol'
  | 'Launcher'
  | 'Special'
  | 'Melee'
  | 'Wonder Weapon';

export interface Bo7Weapon {
  /** Rank by Legendary+Triple PaP DPS (1 = highest). */
  rank: number;
  name: string;
  /** Base gun name with the parenthetical attachment/variant stripped. */
  baseWeapon: string;
  /** Attachment / variant label (parenthetical), or null for the stock gun. */
  variant: string | null;
  weaponClass: WeaponClass;
  /** Baseline (Legendary + Triple PaP) damage per shot. */
  damagePerShot: number;
  /** Rate of fire in RPM (unchanged by rarity/PaP). */
  rpm: number;
  /** Baseline (Legendary + Triple PaP) damage per second. */
  dps: number;
  /** DPS percentile within the BO7 sample (0-1). */
  percentile: number;
  tier: DpsTier;
  /** DPS as a fraction of the #1 gun (0-1). */
  percentOfTopGun: number;
}

