export const weaponClasses: WeaponClass[] = [
  'Assault Rifle',
  'SMG',
  'LMG',
  'Marksman Rifle',
  'Sniper',
  'Shotgun',
  'Pistol',
  'Launcher',
  'Special',
  'Melee',
  'Wonder Weapon',
];

/** A base gun and all of its attachment/variant entries. */
export interface WeaponGroup {
  baseWeapon: string;
  weaponClass: WeaponClass;
  /** Variants sorted by DPS (highest first). */
  variants: Bo7Weapon[];
  /** Best (highest-DPS) variant for this base gun. */
  best: Bo7Weapon;
}

/**
 * Group the weapon list by base gun, preserving the incoming order of the
 * `weapons` array for `best` selection is by DPS. Each group's variants are
 * sorted by DPS descending.
 */
export function groupByBaseWeapon(weapons: Bo7Weapon[]): WeaponGroup[] {
  const map = new Map<string, Bo7Weapon[]>();
  for (const w of weapons) {
    const list = map.get(w.baseWeapon);
    if (list) list.push(w);
    else map.set(w.baseWeapon, [w]);
  }
  const groups: WeaponGroup[] = [];
  for (const [baseWeapon, variants] of map) {
    const sorted = [...variants].sort((a, b) => b.dps - a.dps);
    groups.push({
      baseWeapon,
      weaponClass: sorted[0].weaponClass,
      variants: sorted,
      best: sorted[0],
    });
  }
  return groups;
}

/** Sorted list of unique base gun names. */
export const baseWeaponNames: string[] = Array.from(
  new Set(bo7Weapons.map((w) => w.baseWeapon)),
).sort((a, b) => a.localeCompare(b));
